package com.bank.accrual.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;

@Entity
@Table(name = "accounts")
public class Account {

    @Id @Column(name = "account_id") private String accountId;
    @Column(name = "holder_name", nullable = false) private String holderName;
    @Column(nullable = false, precision = 15, scale = 2) private BigDecimal balance;
    @Column(name = "interest_rate", nullable = false, precision = 5, scale = 2) private BigDecimal interestRate;
    @Column(nullable = false, precision = 15, scale = 2) private BigDecimal accrued;
    @Column(name = "last_accrued") private LocalDate lastAccrued;

    protected Account() {}

    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }

    // Idempotent daily accrual: setting (not adding) today's accrual makes re-running a chunk safe
    public void accrueDaily(LocalDate today) {
        BigDecimal daily = balance.multiply(interestRate)
            .divide(new BigDecimal("36500"), 2, RoundingMode.HALF_UP); // rate%/365, 2dp
        this.accrued = daily;              // idempotent for a given day
        this.lastAccrued = today;
    }

    public BigDecimal getAccrued() { return accrued; }
    public LocalDate getLastAccrued() { return lastAccrued; }
}
