    @Column(name = "cursor_val", nullable = false) private String cursorVal;
    @Column(name = "updated_at") private LocalDateTime updatedAt;

    protected JobCheckpoint() {}
    public JobCheckpoint(String jobName, String cursorVal) {
        this.jobName = jobName; this.cursorVal = cursorVal; this.updatedAt = LocalDateTime.now();
    }
    public String getCursorVal() { return cursorVal; }
    public void advance(String cursorVal) { this.cursorVal = cursorVal; this.updatedAt = LocalDateTime.now(); }
}
