package com.bank.accrual.service;

import com.bank.accrual.dto.AccrualResult;
import com.bank.accrual.model.Account;
import com.bank.accrual.model.JobCheckpoint;
import com.bank.accrual.repository.AccountRepository;
import com.bank.accrual.repository.JobCheckpointRepository;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDate;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class InterestAccrualService {

    private static final String JOB = "interest-accrual";

    private final AccountRepository accountRepo;
    private final JobCheckpointRepository checkpointRepo;
    private final EntityManager entityManager;

    @Value("${accrual.chunk-size:500}") private int chunkSize;
    @Value("${accrual.throttle-ms:50}") private long throttleMs;

    // Orchestrates chunked processing: bounded memory, per-chunk commit, resumable, throttled
    public AccrualResult run() {
        LocalDate today = LocalDate.now();
        JobCheckpoint checkpoint = checkpointRepo.findById(JOB)
            .orElseGet(() -> checkpointRepo.save(new JobCheckpoint(JOB, "")));
        String cursor = checkpoint.getCursorVal();   // resume from last committed cursor

        int processed = 0, skipped = 0, chunks = 0;
        List<Account> chunk;
        do {
            chunk = accountRepo.findNextChunk(cursor, PageRequest.of(0, chunkSize)); // bounded read
            if (chunk.isEmpty()) break;

            int[] counts = processChunk(chunk, today);   // PER-CHUNK transaction
            processed += counts[0];
            skipped += counts[1];
            chunks++;

            cursor = chunk.get(chunk.size() - 1).getAccountId();
            advanceCheckpoint(cursor);                   // durable progress → resumable
            throttle();                                  // be a good DB citizen
        } while (chunk.size() == chunkSize);

        // finished → reset cursor for next night's run
        advanceCheckpoint("");
        log.info("Accrual complete: processed={}, skipped={}, chunks={}", processed, skipped, chunks);
        return new AccrualResult(processed, skipped, chunks, cursor);
    }

    // Each chunk commits independently; completed chunks survive a later failure
    @Transactional
    public int[] processChunk(List<Account> chunk, LocalDate today) {
        int ok = 0, bad = 0;
        for (Account a : chunk) {
            try {
                a.accrueDaily(today);   // idempotent — safe to re-run on restart
                ok++;
            } catch (Exception e) {
                // SKIP-AND-LOG a poison record instead of aborting the whole chunk
                log.warn("Skipping account {}: {}", a.getAccountId(), e.getMessage());
                bad++;
            }
        }
        entityManager.flush();   // write the chunk
        entityManager.clear();   // DETACH entities → release heap (prevents OOM)
        return new int[]{ok, bad};
    }

    @Transactional
    public void advanceCheckpoint(String cursor) {
        JobCheckpoint cp = checkpointRepo.findById(JOB).orElseThrow();
        cp.advance(cursor);
        checkpointRepo.save(cp);
    }

    private void throttle() {
        try { Thread.sleep(throttleMs); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}
