package com.bank.accrual.job;

import com.bank.accrual.dto.AccrualResult;
import com.bank.accrual.service.InterestAccrualService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
@RequiredArgsConstructor
@Slf4j
public class InterestAccrualJob {

    private final InterestAccrualService service;

    // Runs nightly at 01:00; delegates immediately to the chunked service
    // NOTE: for very large, restartable, auditable batches, prefer Spring Batch.
    @Scheduled(cron = "0 0 1 * * *")
    public void nightlyAccrual() {
        log.info("Starting nightly interest accrual job");
        AccrualResult result = service.run();
        log.info("Nightly accrual finished: {}", result);
    }
}
