package com.bank.accrual.service;

import com.bank.accrual.model.Account;
import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import java.math.BigDecimal;
import java.time.LocalDate;
import static org.assertj.core.api.Assertions.*;

class ChunkProcessingTest {

    private Account account(String id, String balance, String rate) throws Exception {
        Account a = Account.class.getDeclaredConstructor().newInstance();
        setField(a, "accountId", id);
        setField(a, "holderName", "Test");
        setField(a, "balance", new BigDecimal(balance));
        setField(a, "interestRate", new BigDecimal(rate));
        setField(a, "accrued", BigDecimal.ZERO);
        return a;
    }

    private void setField(Object o, String name, Object val) throws Exception {
        Field f = o.getClass().getDeclaredField(name);
        f.setAccessible(true);
        f.set(o, val);
    }

    @Test
    void dailyAccrualIsIdempotent() throws Exception {
        Account a = account("SAV0001", "1000000.00", "4.00");
        a.accrueDaily(LocalDate.now());
        BigDecimal first = a.getAccrued();
        a.accrueDaily(LocalDate.now());   // re-run (restart) → same value, not doubled
        assertThat(a.getAccrued()).isEqualByComparingTo(first);
    }

    @Test
    void accrualIsBalanceTimesRateOver36500() throws Exception {
        Account a = account("SAV0001", "1000000.00", "4.00");
        a.accrueDaily(LocalDate.now());
        // 1,000,000 * 4 / 36500 = 109.59 (2dp)
        assertThat(a.getAccrued()).isEqualByComparingTo("109.59");
    }

    @Test
    void chunkSizeBoundsMemoryAndDbLoad() {
        // A bounded chunk of 500 caps rows in memory per iteration and per read.
        int chunk = 500, total = 10_000_000;
        int chunks = (total + chunk - 1) / chunk;
        assertThat(chunks).isEqualTo(20000); // processed 500 at a time, not all at once
    }

    @Test
    void cursorAdvancesPastLastProcessedId() {
        // Keyset: next read is WHERE account_id > lastCursor → resumable, no OFFSET scan.
        String lastCursor = "SAV0500";
        assertThat("SAV0501".compareTo(lastCursor)).isGreaterThan(0);
    }
}
